538	      private readonly route = inject(ActivatedRoute);
539	      private readonly router = inject(Router);
540	      private readonly eventsApi = inject(EventsApiService);
541	      private readonly bookingsApi = inject(BookingsApiService);
542	      private readonly selection = inject(BookingSelectionService);
543	
544	      readonly seatMap = signal<SeatMap | null>(null);
545	      readonly event = signal<EventDetail | null>(null);
546	      readonly loading = signal(true);
547	      readonly notFound = signal(false);
548	      readonly loadError = signal(false);
