554	      constructor() {
555	        const id = Number(this.route.snapshot.paramMap.get('id'));
556	        if (!Number.isInteger(id) || id > 2147483647) {
557	          this.loading.set(false);
558	          this.notFound.set(true);
559	          return;
560	        }
561	        this.eventId = id;
562	
563	        forkJoin({
564	          seatMap: this.eventsApi.getSeatMap(id),
565	          event: this.eventsApi.getEvent(id)
566	        }).subscribe({
567	          next: ({ seatMap, event }) => {
568	            this.seatMap.set(seatMap);
569	            this.event.set(event);
570	            this.selection.setPriceCategories(event.preiskategorien);
571	            this.loading.set(false);
572	          },
573	          error: (err: HttpErrorResponse) => {
574	            this.loading.set(false);
575	            if (err.error?.code === 'EVENT_NOT_FOUND') {
576	              this.notFound.set(true);
577	            } else {
578	              this.loadError.set(true);
579	            }
580	          }
581	        });
