588	          preiskategorieId: seat.priceCategoryId as number // Button nur aktiv, wenn allSelectedSeatsHaveCategory() true ist
589	        }));
590	
591	        this.submitting.set(true);
592	        this.submitError.set(null);
593	
594	        this.bookingsApi
595	          .createBooking({ eventId: this.eventId, name: daten.name, email: daten.email, positionen })
596	          .subscribe({
597	            next: booking => {
598	              this.router.navigate(['/buchungen', booking.reference], { state: { booking } });
599	            },
600	            error: () => {
