1	using Microsoft.Data.SqlClient;
2	using Microsoft.EntityFrameworkCore;
3	using seed_a_backend.Api.Domain;
4	using seed_a_backend.Api.Infrastructure;
5	
6	namespace seed_a_backend.Tests;
7	
8	/// <summary>
9	/// Verifiziert die per DB-CHECK-Constraint erzwungene Invariante, dass `BookingPosition.BookingId`
10	/// und `PriceCategoryId` immer gemeinsam null oder gemeinsam gesetzt sind (AD-2), statt sie nur
11	/// über einen XML-Doc-Kommentar zu dokumentieren.
12	/// </summary>
13	public class BookingPositionInvariantTests : IAsyncLifetime
14	{
15	    private readonly SqlServerTestDatabase _database = new();
16	
17	    public ValueTask InitializeAsync() => _database.InitializeAsync();
18	
19	    public ValueTask DisposeAsync() => _database.DisposeAsync();
20	
21	    /// <summary>
22	    /// Prüft nicht nur den Exception-Typ, sondern dass die `DbUpdateException` tatsächlich vom
23	    /// erwarteten CHECK-Constraint stammt (SQL-Server-Fehlernummer 547 für CHECK-/FK-Verletzungen,
24	    /// plus Constraint-Name in der Meldung) — sonst würde auch eine zufällige `DbUpdateException`
25	    /// aus einer anderen Ursache (z. B. FK- oder Unique-Index-Verletzung) den Test bestehen lassen.
26	    /// </summary>
27	    private static async Task AssertViolatesCheckConstraintAsync(Func<Task> saveChanges)
28	    {
29	        var ex = await Assert.ThrowsAsync<DbUpdateException>(saveChanges);
30	        var sqlException = Assert.IsType<SqlException>(ex.InnerException);
31	        Assert.Equal(547, sqlException.Number);
32	        Assert.Contains(AppDbContext.BookingPositionBeideNullOderBeideGesetztConstraintName, sqlException.Message);
33	    }
34	
35	    private static async Task<(int EventId, int PriceCategoryId, int BookingId)> SeedGraphAsync(AppDbContext db, CancellationToken ct)
36	    {
37	        var @event = new Event { Titel = "Testkonzert", Beschreibung = "Beschreibung", Zeitpunkt = DateTime.UtcNow, DauerMinuten = 90, Altersfreigabe = 0 };
38	        var room = new Room { Name = "Saal 1", RowLabels = ["A"], ColumnCount = 5, Events = [@event] };
39	        var venue = new Venue { Name = "Testhalle", Rooms = [room] };
40	        var priceCategory = new PriceCategory { Name = "Standard", Preis = 10m };
41	        @event.PriceCategories.Add(priceCategory);
42	        var booking = new Booking { Reference = "ABCD2345", Name = "Erika Musterfrau", Email = "erika@example.com" };
43	
44	        db.Venues.Add(venue);
45	        db.Bookings.Add(booking);
46	        await db.SaveChangesAsync(ct);
47	
48	        return (@event.Id, priceCategory.Id, booking.Id);
49	    }
50	
51	    [Fact]
52	    public async Task BookingId_gesetzt_ohne_PriceCategoryId_verletzt_die_Check_Constraint()
53	    {
54	        var ct = TestContext.Current.CancellationToken;
55	        await using var db = _database.CreateContext();
56	        var (eventId, _, bookingId) = await SeedGraphAsync(db, ct);
57	
58	        db.BookingPositions.Add(new BookingPosition
59	        {
60	            EventId = eventId,
61	            RowLabel = "A",
62	            ColumnNumber = 1,
63	            BookingId = bookingId,
64	            PriceCategoryId = null,
65	        });
66	
67	        await AssertViolatesCheckConstraintAsync(() => db.SaveChangesAsync(ct));
68	    }
69	
70	    [Fact]
71	    public async Task PriceCategoryId_gesetzt_ohne_BookingId_verletzt_die_Check_Constraint()
72	    {
73	        var ct = TestContext.Current.CancellationToken;
74	        await using var db = _database.CreateContext();
75	        var (eventId, priceCategoryId, _) = await SeedGraphAsync(db, ct);
76	
77	        db.BookingPositions.Add(new BookingPosition
78	        {
79	            EventId = eventId,
80	            RowLabel = "A",
81	            ColumnNumber = 1,
82	            BookingId = null,
83	            PriceCategoryId = priceCategoryId,
84	        });
85	
86	        await AssertViolatesCheckConstraintAsync(() => db.SaveChangesAsync(ct));
87	    }
88	
